+package org.apache.streampipes.rest.shared.security;
+
+import java.net.Inet6Address;
+import java.net.InetAddress;
+import java.net.URI;
+import java.net.URISyntaxException;
+import java.net.UnknownHostException;
+
+public final class EndpointUrlValidator {
+
+  private EndpointUrlValidator() {
+  }
+
+  public static String validate(String rawUrl) {
+    URI uri = parse(rawUrl);
+
+    if (!("http".equalsIgnoreCase(uri.getScheme()) || "https".equalsIgnoreCase(uri.getScheme()))) {
+      throw new IllegalArgumentException("Only HTTP(S) endpoints are allowed");
+    }
+
+    if (uri.getHost() == null || uri.getHost().isBlank()) {
+      throw new IllegalArgumentException("Endpoint host is missing");
+    }
+
+    if (uri.getUserInfo() != null) {
+      throw new IllegalArgumentException("Endpoints with user info are not allowed");
+    }
+
+    validateResolvedAddresses(uri.getHost());
+    return uri.toString();
+  }
+
+  private static URI parse(String rawUrl) {
+    try {
+      return new URI(rawUrl);
+    } catch (URISyntaxException e) {
+      throw new IllegalArgumentException("Invalid endpoint URL", e);
+    }
+  }
+
+  private static void validateResolvedAddresses(String host) {
+    final InetAddress[] addresses;
+    try {
+      addresses = InetAddress.getAllByName(host);
+    } catch (UnknownHostException e) {
+      throw new IllegalArgumentException("Endpoint host cannot be resolved", e);
+    }
+
+    for (InetAddress address : addresses) {
+      if (isBlocked(address)) {
+        throw new IllegalArgumentException("Endpoint host resolves to a non-public address");
+      }
+    }
+  }
+
+  private static boolean isBlocked(InetAddress address) {
+    if (address.isAnyLocalAddress()
+        || address.isLoopbackAddress()
+        || address.isLinkLocalAddress()
+        || address.isSiteLocalAddress()
+        || address.isMulticastAddress()) {
+      return true;
+    }
+
+    byte[] raw = address.getAddress();
+
+    // 100.64.0.0/10 (shared address space)
+    if (raw.length == 4
+        && (raw[0] & 0xFF) == 100
+        && ((raw[1] & 0xC0) == 0x40)) {
+      return true;
+    }
+
+    // 169.254.0.0/16 (already covered by isLinkLocalAddress for IPv4, kept explicit)
+    if (raw.length == 4
+        && (raw[0] & 0xFF) == 169
+        && (raw[1] & 0xFF) == 254) {
+      return true;
+    }
+
+    // IPv6 unique local fc00::/7
+    if (address instanceof Inet6Address && raw.length == 16) {
+      int first = raw[0] & 0xFF;
+      if ((first & 0xFE) == 0xFC) {
+        return true;
+      }
+    }
+
+    // 0.0.0.0/8
+    if (raw.length == 4 && (raw[0] & 0xFF) == 0) {
+      return true;
+    }
+
+    // 127.0.0.0/8 (already covered by isLoopbackAddress for IPv4, kept explicit)
+    if (raw.length == 4 && (raw[0] & 0xFF) == 127) {
+      return true;
+    }
+
+    // 224.0.0.0/4
+    if (raw.length == 4 && ((raw[0] & 0xF0) == 0xE0)) {
+      return true;
+    }
+
+    return false;
+  }
+}

